// Author: MiYu. Reuse classic SLK metadata and original-before-custom placement overrides.
#include "placed_definition.h"
#include "object_data.h"
#include "binary.h"
#include <cmath>

namespace war3 {
std::string placedString(const SourceTable::Row& row,const char* key,const std::string& fallback) {auto found=row.find(key);return found==row.end()?fallback:found->second;}
float placedNumber(const SourceTable::Row& row,const char* key,float fallback) {auto v=placedString(row,key);auto first=v.find_first_not_of(" \t\r\n");v=first==std::string::npos?"":v.substr(first,v.find_last_not_of(" \t\r\n")-first+1);if(v.empty() || v=="_" || v=="-")return fallback;size_t end=0;auto result=std::stof(v,&end);if(!std::isfinite(result) || end!=v.size())throw std::runtime_error("Invalid placed source field: "+std::string(key));return result;}
PlacedDefinitions readPlacedDefinitions(Archives& archives,const char* table,const char* metadata,const char* overlay,bool levels,unsigned& unmapped) {
    auto source=SourceTable::read(archives,table),meta=SourceTable::read(archives,metadata);PlacedDefinitions rows,fields;for(auto& row:source.rows()){auto id=placedString(row,source.idColumn().c_str());if(id.size()==4)rows[ObjectData::code(id)]=row;}for(auto& row:meta.rows()){auto id=placedString(row,meta.idColumn().c_str());if(id.size()==4)fields[ObjectData::code(id)]=row;}
    auto bytes=archives.readCandidates({overlay},ArchiveScope::Map);if(!bytes)return rows;Binary b(bytes->bytes);auto version=b.u32();if(version!=1 && version!=2)throw std::runtime_error("Unsupported placed object override version");auto raw=[&]{auto code=b.take(4);return ObjectData::code({reinterpret_cast<const char*>(code.data()),4});};unsigned missing=0;
    for(bool custom:{false,true}){auto count=b.count(12,65536);for(unsigned i=0;i<count;++i){auto base=raw(),id=raw();if(!rows.contains(base))throw std::runtime_error("Placed override base not found: "+ObjectData::name(base));if(!custom)id=base;else if(rows.contains(id))throw std::runtime_error("Duplicate placed custom ID");auto target=rows.at(base);auto changes=b.count(levels?21:13,262144);for(unsigned n=0;n<changes;++n){auto field=raw(),type=b.u32();int level=0,pointer=0;if(levels){level=b.i32();pointer=b.i32();}std::string replacement;switch(type){case 0:replacement=std::to_string(b.i32());break;case 1:case 2:replacement=std::to_string(b.f32());break;case 3:replacement=b.cstring();break;default:throw std::runtime_error("Unknown placed object field type");}auto marker=raw();if(marker && marker!=base && marker!=id)throw std::runtime_error("Invalid placed override terminator");auto found=fields.find(field);if(found==fields.end() || pointer!=0){++missing;continue;}auto key=placedString(found->second,"field");if(key.empty()){++missing;continue;}int repeat=int(placedNumber(found->second,"repeat"));if(repeat){if(level<1 || level>repeat || level>99)throw std::runtime_error("Invalid doodad override variation");key+=(level<10?"0":"")+std::to_string(level);}target[key]=std::move(replacement);}rows[id]=std::move(target);}}b.finish();unmapped=missing;return rows;
}
std::string placedModel(const SourceTable::Row& row,int variation,Archives& archives) {auto name=placedString(row,"file");if(name.empty() || name=="_")throw std::runtime_error("Placed object has no source model");int count=int(placedNumber(row,"numVar",1));if(name.ends_with(".mdl") || name.ends_with(".mdx"))name.resize(name.size()-4);if(count>1){if(variation<0 || variation>=count)throw std::runtime_error("Placed model variation outside source range");auto variant=name+std::to_string(variation)+".mdx";if(archives.read(variant) || !archives.read(name+".mdx"))return variant;}return name+".mdx";}
}
